mapper.select:
select
con.Con_Name as conName, con.Con_Code as conCode, con.Con_Money_Total as conMoneyTotal, con.Con_Party_B_Id as conPartyBId, c1.C_Name as conPartyBName, c1.C_Name_History as conPartyBNameHistory, c1.C_Abbreviation as conPartyBAbbName, c2.C_Name as vrCname, dp.D_Name as vrDname, cl.Cl_Code as clCode, cl.Cl_Title as clTitle, cl.Cl_Location as clLocation, f.file_relation_id as fileRelationId, enis.Enis_Project_Name as enisName, enis.Enis_Code as enisCode, mn.* from Con_Visa_Record mn
left join Con_Contract con on con.Con_Id=mn.Con_Id left join Con_Contact_List cl on cl.Cl_Id=mn.Vr_Cl_Id left join Sys_File f on f.FileID=mn.Vr_Id left join SYS_Company c1 on con.Con_Party_B_Id=c1.C_Id left join Con_Enis enis on enis.Enis_Id=mn.Enis_Id left join Sys_Company c2 on c2.C_Id=mn.Vr_Cid left join Sys_Department dp on dp.D_Id=mn.Vr_Did ${params.authSql}
and mn.Te_Id = #{params.teId}
and mn.P_Id = #{params.pId}
and mn.Vr_State = #{params.vrState}
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and mn.Vr_Code like concat('%',#{params.vrCode},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
and enis.Enis_Project_Name like concat('%',#{params.enisName},'%')
and mn.Vr_Id in (select Vr_Id from Con_Visa_Fee where Vf_State!=3 and Vr_Id is not null)
and mn.Vr_Id not in (select Vr_Id from Con_Visa_Fee where Vf_State!=3 and Vr_Id is not null)
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Vr_Create_Time DESC
